import logging
import string

from falcon import HTTP_200
from requests_toolbelt.multipart.decoder import (
    MultipartDecoder, NonMultipartContentTypeException,
    ImproperBodyPartContentException)

from taf.gnb.oam.ne3s.ws.components.connection.notification_factory import NotificationFactory

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class FilesResource(object):
    def on_get(self, req, resp):
        filename = req.path.split('/files')[-1]
        with open(filename, 'rb') as f:
            content = f.read()

        resp.status = HTTP_200
        resp.data = content


class NotificationResource(object):
    WINDOWS_LINE_ENDING = b'\r\n'
    UNIX_LINE_ENDING = b'\n'

    def __init__(self, notification_queue):
        self.notification_queue = notification_queue

    def _get_next_chunk_size(self, request):
        """
        Each chunk is preceded by its size in bytes given as hexadecimal
        and surrounded by CRLF, except first one that is not preceded by CRLF.
        The transmission ends when a zero-length chunk is received.
        """
        try:
            line = request.stream.readline()
            # CRLF preceding chunk size occurs just after the last data byte,
            # if the last data byte is LF than CRLF will be placed in next line.
            if line == b'\r\n':
                line = request.stream.readline()
            return int(line, 16)
        except ValueError:
            log.warn('Converting chunk size from hex="{}" to dec failed.'.format(line.strip()))
            return 0

    def _read_chunked_transfer_encoding(self, request):
        """
        Workaround for request.stream.read() call that blocks chunked transfer encoding for around 30s,
        therefore manager doesn't acknowledge the change notification being sent by agent.
        As a result, further progress of some operations that have to exchange multiple
        messages might be blocked and agent is then not ready to process of any new request.
        """
        data = b''
        chunk_size = self._get_next_chunk_size(request)
        content_length = chunk_size
        while chunk_size:
            line = request.stream.readline()
            data += line
            if len(data) >= content_length:
                # CRLF preceding chunk size occurs just after the last data byte
                # but it isn't part of the data and must be removed.
                data = data[:-2] if data.endswith(b'\r\n') else data
                chunk_size = self._get_next_chunk_size(request)
                content_length += chunk_size
        return data

    def _get_request_content(self, request):
        if request.content_length is None:
            if request.headers.get('TRANSFER-ENCODING') == 'chunked':
                data = self._read_chunked_transfer_encoding(request)
            else:
                data = request.stream.read()
        else:
            data = request.bounded_stream.read()

        # Some multipart notifications have their part's content-length
        # written just before the boundary. We do not need to know this value
        # and it is breaking MultipartDecoder, so we remove unnecessary
        # content-length from the data.
        boundary_start = '--'.encode()
        if boundary_start in data:
            data = data[data.find(boundary_start):]

        # MultipartDecoder insists on having Windows line ending
        if b'\r\n\r\n' not in data:
            formatted_data = data.replace(self.UNIX_LINE_ENDING,
                                          self.WINDOWS_LINE_ENDING)
        else:
            formatted_data = data

        return formatted_data

    def on_post(self, request, resp, filter_name, msg_group):
        formatted_data = self._get_request_content(request)
        log.debug("New Request {}".format(formatted_data))

        try:
            decoded = MultipartDecoder(formatted_data, request.content_type)
            parts = list(filter(self._is_part_correct, decoded.parts))
        except (NonMultipartContentTypeException, ImproperBodyPartContentException):
            parts = [formatted_data]

        notifications = NotificationFactory.from_parts(
            filter_name, msg_group, *parts)

        for notification in notifications:
            self.notification_queue.put(notification)

        resp.status = HTTP_200

    @staticmethod
    def _is_part_correct(part):
        """ In some cases, MultipartDecoder makes an incorrect part. We check if
        the part consists of just hexadecimal number. If so, it is incorrect."""
        return not all(c in string.hexdigits for c in part.content.decode(errors='ignore'))
